// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract C { event Changed(address indexed who, uint8 indexed kind, uint256 value); event Anonymous(uint8 indexed kind, uint256 value) anonymous; function fire(uint8 kind, uint256 value) external { emit Changed(msg.sender, kind, value); emit Anonymous(kind, value + 1); } }
